        if(matched.some(q=>q.x===x&&q.top<a.end&&q.end>a.top)||partials.some(q=>q.left<left+tw&&q.left+q.width>left&&q.top<a.end&&q.end>a.top)||[...framed,...enclosed].some(q=>q.x0<left+tw&&q.x0+q.width>left&&q.y0<a.end&&q.y0+q.height>a.top)||connected.some(q=>q.x===x&&q.top<a.end&&q.end>a.top))continue;
        if(anchors.some(q=>(q.right===left||q.left===left+tw)&&q.top<a.end&&q.end>a.top&&(q.top!==a.top||q.end!==a.end)))continue;
