          let topRows=0,edgeCols=0;
          while(topRows<height&&rowKey(left,off+a.top+topRows)===rowKey(ref.x*tw,off+ref.top+topRows))topRows++;
          while(edgeCols<tw){const u=dir>0?edgeCols:tw-1-edgeCols;if(key(left+u,off+a.top,1,height)!==key(ref.x*tw+u,off+ref.top,1,height))break;edgeCols++;}
