        if(closed.some(q=>q.left<left+tw&&q.right>left&&q.top<a.end&&q.end>a.top)||closed.some(q=>(q.right===left||q.left===left+tw)&&q.top<a.end&&q.end>a.top&&(q.top!==a.top||q.end!==a.end)))continue;
