        if(refs.length<2)continue;
        const owned=(x,y)=>pieces.some(q=>q.role==='wall'&&q.x0<=x&&q.x1>x&&q.y0<=y&&q.y1>y&&q.transform.start===p.top&&q.transform.end===p.end&&q.transform.high===2&&q.transform.low===1);
        const x0=p.dir>0?p.edgeCols:0,x1=p.dir>0?tw:tw-p.edgeCols,inner=p.dir>0?x0-1:x1;
        let closed=true;for(let x=x0;x<x1;x++)if(!owned(p.left+x,p.top+p.topRows-1))closed=false;
        for(let y=p.top+p.topRows;y<p.end;y++)if(!owned(p.left+inner,y))closed=false;
        if(!closed)continue;
