        let clear=true;for(let y=start;y<a.end;y++)for(let x=left;x<left+tw;x++)if(moldingMask[(off+y)*w+x]||(ownPhase?phaseFloor.has(keys[Math.floor(y/th)]?.[Math.floor(x/tw)]):keys[Math.floor(y/th)][Math.floor(x/tw)]===floorKey))clear=false;
