          const ownedHead=outerBoundaryClosed(a.x,a.top)&&pieces.some(p=>
            (p.x1===a.x*tw||p.x0===(a.x+1)*tw)&&p.x1-p.x0===tw&&p.y0===a.top&&p.y1===a.end&&
            p.transform.start===a.top&&p.transform.end===a.end&&p.transform.high===2&&p.transform.low===1&&
            key(p.x0,off+p.y0,tw,p.y1-p.y0)===a.body);
