        const same=(a,b)=>a.y0===b.y0&&a.y1===b.y1&&a.위===b.위&&a.아래===b.아래;
        const sources=walls.map(sx=>(j.축대구간||[]).find(t=>t.x===sx/j.TW&&t.y0===row&&!t.계단&&t.위===j.실내벽.높은층&&t.아래===j.실내벽.바닥층));
