    j._실내범위근거={method:'prepared-indoor-category-v1',source:'_맵유형.json',map:j.맵,
      category:typeof 유형==='string'?유형:null,eligible:대상.적용,reason:대상.이유,
      existingIndoor:!!j.실내벽,manualPreserved:!!(대상.적용&&!j.실내벽&&(j.축대구간?.length||j.건물?.length||j.지형높이.some(h=>h!==1)))};
