    if(j.축대구간?.length||j.건물?.length||j.지형높이.some(h=>h!==1))return {status:'수동 지정 보존'};
    const pixels=im=>{const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const g=c.getContext('2d');g.drawImage(im,0,0);return g.getImageData(0,0,c.width,c.height).data;};
    const key=(d,w,x,y,tw,th)=>{let k='';for(let b=0;b<th;b++)for(let a=0;a<tw;a++){const p=((96+y*th+b)*w+x*tw+a)*4;k+=String.fromCharCode(d[p],d[p+1],d[p+2],d[p+3]);}return k;};
    let stairReference=null;
