        terraceProfiles.push({left:t.x>0?Array.from({length:t.y1-t.y0+3},(_,i)=>key(d,im.width,t.x-1,t.y0-1+i,ref.TW,ref.TH)):null,right:t.x+1<ref.W?Array.from({length:t.y1-t.y0+3},(_,i)=>key(d,im.width,t.x+1,t.y0-1+i,ref.TW,ref.TH)):null,tiles:Array.from({length:t.y1-t.y0+3},(_,i)=>key(d,im.width,t.x,t.y0-1+i,ref.TW,ref.TH)),
          above:ref.지형높이[(t.y0-1)*ref.W+t.x],heights:Array.from({length:t.y1-t.y0+1},(_,i)=>ref.지형높이[(t.y0+i)*ref.W+t.x]),
          top:t.위,bottom:t.아래});
