      if(side)sideProfiles.push({context:Array.from({length:side.y1-side.y0+3},(_,i)=>[-1,0,1].map(dx=>side.x+dx>=0&&side.x+dx<ref.W?key(d,im.width,side.x+dx,side.y0-1+i,ref.TW,ref.TH):null)),top:side.위,bottom:side.아래,body:Array.from({length:side.y1-side.y0+1},(_,i)=>key(d,im.width,side.x,side.y0+i,ref.TW,ref.TH))});
