        const cells=[];for(let v=-1;v<=1;v++)for(let u=-1;u<=1;u++){const x=start[0]+u,y=start[1]+v;cells.push({key:key(d,im.width,x,y,ref.TW,ref.TH),walk:!!ref.갈수?.[y*ref.W+x]});}
